import {loadCanonical20260927Adapter,CANONICAL_20260927_VERSION} from '../compatibility/canonical-20260927-adapter.mjs';
import {CanonicalWorld} from '../world/service.mjs';
import {positionCell,tileAt} from '../world/definition.mjs';
import {shopItems,itemUnlocked} from '../economy/contract.mjs';
import {candidateConvenience,selectCandidateDex} from './candidate-convenience.mjs';

export const CANDIDATE_QA_KEY='geoje.monsters.qa.canonical-20260927.v1';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action)=>`<button type="button" data-action="${esc(action)}">${esc(label)}</button>`;
export function candidateViewport(world){
 const map=world.map,{x,y}=positionCell(world.snapshot().position),actors=new Map(map.actors.map(a=>[`${a.x},${a.y}`,a])),points=new Map(map.points.map(id=>world.definition.points[id]).filter(Boolean).map(p=>[`${p.x},${p.y}`,p]));
 const rows=[];for(let yy=y-4;yy<=y+4;yy++){const cells=[];for(let xx=x-5;xx<=x+5;xx++){const tile=tileAt(map,xx,yy),actor=actors.get(`${xx},${yy}`),point=points.get(`${xx},${yy}`),symbol=xx===x&&yy===y?'●':actor?'T':point?'◇':tile.water?'≈':tile.walkable?'·':'█';cells.push(`<span title="${esc(point?.label??actor?.id??tile.name)}" aria-label="${esc(point?.label??actor?.id??tile.name)}">${symbol}</span>`)}rows.push(`<div>${cells.join('')}</div>`)}
 return `<div role="img" aria-label="현재 위치 중심 11×9 지도" style="display:inline-block;background:#203844;padding:.6rem;font:18px/1.3 monospace;letter-spacing:.15em">${rows.join('')}</div><p>● 나 · T Trainer/NPC · ◇ 조사 · ≈ 물 · █ 통행 불가</p>`;
}
export function candidatePanel(view,{tab='overview',dexFilter='all',areaId='',textSpeed='normal',reducedMotion=false,highContrast=false,typeId='fire'}={}){
 const nav=['overview','world','story','dex','research','help'].map((id,i)=>button(['목표','월드','진행','도감','현장 조사','설정/도움말'][i],`tab:${id}`)).join('');
 let body='';
 if(tab==='overview')body=`<h2>현재 목표</h2><p>${esc(view.objective)}</p><p>현재 지역: ${esc(view.stage.title)}</p><h3>POST 체크리스트</h3><ul>${view.post.map(x=>`<li>${x.completed?'✓':'○'} ${esc(x.name)}</li>`).join('')}</ul>`;
 if(tab==='world')body=`<h2>월드 발견</h2><p>${view.maps.filter(x=>x.discovered).length}/${view.maps.length} 맵</p><ul>${view.maps.map(x=>`<li>${x.discovered?'✓':'○'} ${esc(x.name)} (${esc(x.stageId)})</li>`).join('')}</ul><h3>랜드마크</h3><ul>${view.landmarks.filter(x=>x.discovered).map(x=>`<li>${x.investigated?'✓':'○'} ${esc(x.name)}${x.message?` · ${esc(x.message)}`:''}</li>`).join('')||'<li>발견한 랜드마크가 없습니다.</li>'}</ul>`;
 if(tab==='story')body=`<h2>체육관과 이야기</h2><ul>${view.stages.map(x=>`<li>${x.completed?'✓':x.current?'▶':'○'} ${esc(x.id)} · ${esc(x.title)}${x.badge?` · ${x.badgeEarned?'배지 획득':'배지 미획득'}`:''}</li>`).join('')}</ul><h3>Trainer 승리 완료</h3><p>${view.trainers.filter(x=>x.defeated).length}/${view.trainers.length}</p><ul>${view.trainers.map(x=>`<li>${x.defeated?'✓':'○'} ${esc(x.name)} · ${esc(x.stageId)} · ${x.required?'필수':'선택'}</li>`).join('')}</ul>`;
 if(tab==='dex'){
  const selected=selectCandidateDex(view,{filter:dexFilter,areaId});
  body=`<h2>도감 ${view.dex.caught}/${view.dex.total}</h2><label>필터 <select data-filter>${[['all','전체'],['seen','발견'],['caught','포획'],['unseen','미발견']].map(([id,label])=>`<option value="${id}" ${dexFilter===id?'selected':''}>${label}</option>`).join('')}</select></label><label>지역 <select data-area><option value="">전체 지역</option><optgroup label="지역별 도감">${view.regions.map(x=>`<option value="${esc(x.id)}" ${areaId===x.id?'selected':''}>${esc(x.id)} ${esc(x.name)} · ${x.caught}/${x.total} (${Math.round(x.caught/x.total*100)||0}%)</option>`).join('')}</optgroup><optgroup label="세부 서식지">${view.areas.map(x=>`<option value="${esc(x.id)}" ${areaId===x.id?'selected':''}>${esc(x.name)} · ${x.caught}/${x.total} (${Math.round(x.caught/x.total*100)||0}%)</option>`).join('')}</optgroup></select></label><ul>${selected.map(mon=>`<li>No.${String(mon.number).padStart(3,'0')} · ${mon.seen?esc(mon.name):'???'} ${mon.caught?'✓ 포획':mon.seen?'발견':'미발견'}${mon.seen?` · 서식 힌트: ${esc(mon.habitatHints.join(', ')||'연구 기록 없음')}`:''}</li>`).join('')}</ul>`;
 }
 if(tab==='research')body=`<h2>현장 조사</h2><p>방문 맵 ${view.fieldResearch.visitedMaps} · 회복 거점 ${view.fieldResearch.visitedHubs} · 랜드마크 조사 ${view.fieldResearch.investigatedLandmarks}</p><p>조사 단계 ${view.fieldResearch.round} · 이번 단계 관찰점 ${view.fieldResearch.observedSites} · ${view.fieldResearch.active?'진행 중':'대기 중'}</p><p>관찰·보고 결과는 기존 조사 거래 기록에서 계산됩니다.</p>`;
 if(tab==='help'){const chart=view.typeChart[typeId]??{},advantage=Object.entries(chart).filter(([,x])=>x===2).map(([x])=>x),immune=Object.entries(chart).filter(([,x])=>x===0).map(([x])=>x);
  body=`<h2>설정과 도움말</h2><label>글자 속도 <select data-speed>${[['normal','보통'],['fast','빠르게'],['instant','즉시']].map(([id,name])=>`<option value="${id}" ${textSpeed===id?'selected':''}>${name}</option>`).join('')}</select></label><label><input type="checkbox" data-motion ${reducedMotion?'checked':''}> 움직임 줄이기</label><label><input type="checkbox" data-contrast ${highContrast?'checked':''}> 높은 대비</label><h3>타입 도움말</h3><label>공격 타입 <select data-type>${view.types.map(id=>`<option value="${esc(id)}" ${typeId===id?'selected':''}>${esc(id)}</option>`).join('')}</select></label><p>효과가 큼: ${esc(advantage.join(', ')||'없음')} · 효과 없음: ${esc(immune.join(', ')||'없음')}</p><p>표에 없는 조합은 1배입니다. 지역 서식 힌트는 도감에서 발견한 종에만 표시됩니다.</p>`;
 }
 return `<nav aria-label="후보 편의 메뉴">${nav}</nav><section aria-live="polite">${body}</section>`;
}

/** Explicit development-only QA route, with a key outside the three user slots. */
export async function startCandidateRuntime({target=document.body,storage=localStorage,loadAdapter=loadCanonical20260927Adapter}={}){
 const adapter=await loadAdapter();
 if(adapter.version!==CANONICAL_20260927_VERSION||!adapter.validation.ready)throw Error('Staged canonical validation failed');
 let saved=null;
 try{const row=JSON.parse(storage.getItem(CANDIDATE_QA_KEY)||'null');if(row?.version===adapter.version)saved=row.snapshot}catch{}
 let world,activeBattle=null,render=()=>{};
 const hooks={battleReady:snapshot=>{activeBattle=snapshot;render('전투 중')}};
 try{world=new CanonicalWorld({adapter,runtime:saved,mode:'development',hooks})}catch{world=new CanonicalWorld({adapter,mode:'development',hooks})}
 const root=document.createElement('main');root.id='candidate-20260927';root.style.cssText='position:fixed;inset:0;z-index:99999;background:#111c26;color:#f6f4e9;overflow:auto;padding:1rem;font:16px/1.5 system-ui';target.append(root);
 const prefs={tab:'overview',dexFilter:'all',areaId:'',textSpeed:'normal',reducedMotion:false,highContrast:false,typeId:'fire'};let busy=false,feedbackTimer=null;
 const persist=()=>storage.setItem(CANDIDATE_QA_KEY,JSON.stringify({version:adapter.version,snapshot:world.snapshot()}));
 render=(message='')=>{const s=world.snapshot(),map=world.map,view=candidateConvenience(s,adapter,world.definition,world.story),near=world.nearby().filter(p=>p.kind!=='enhanced-league'&&p.kind!=='enhanced-league-info');
  const battleMarkup=activeBattle?`<section><h2>전투 · ${esc(activeBattle.phase)}</h2><p>${esc(activeBattle.opponents?.[activeBattle.enemyActive]?.speciesId??'상대')} · HP ${activeBattle.opponents?.[activeBattle.enemyActive]?.hp??'?'}</p><p>파티 ${activeBattle.active+1} · HP ${activeBattle.party?.[activeBattle.active]?.hp??'?'}</p>${activeBattle.party?.[activeBattle.active]?.moves?.map(m=>button(`${m.id} · PP ${m.pp}`,`battle:move:${m.id}`)).join('')??''}${activeBattle.party?.map((m,i)=>button(`교대 ${i+1} · HP ${m.hp}`,`battle:switch:${i}`)).join('')??''}${button('도망','battle:flee')}${['ecology_ball','affinity_ball','resonance_ball','geoje_ball'].filter(id=>s.inventory?.[id]>0).map(id=>button(`${id} ×${s.inventory[id]}`,`battle:capture:${id}`)).join('')}${Object.entries(activeBattle.bagItems??{}).filter(([id,n])=>n>0&&world.catalog.itemContract[id]?.pocket==='items').flatMap(([id,n])=>activeBattle.party.map((mon,i)=>button(`${world.catalog.itemContract[id].name} ×${n} → ${i+1}`,`battle:item:${id}:${mon.instanceId}`))).join('')}</section>`:'';
  root.style.background=prefs.highContrast?'#000':'#111c26';root.style.color=prefs.highContrast?'#fff':'#f6f4e9';
  const shopMarkup=near.filter(p=>p.kind==='shop').map(p=>`<details><summary>${esc(p.label)} · 자금 ${s.economy?.money??'—'}</summary>${shopItems(world.catalog,{hubId:p.hubId}).filter(item=>itemUnlocked(s,item)).map(item=>button(`${item.name} · ${item.price}`,`purchase:${p.id}:${item.id}`)).join('')}</details>`).join('');
  const itemMarkup=s.party?.length?`<details><summary>도구 사용</summary>${Object.entries(s.progress.items).filter(([id,n])=>n>0&&world.catalog.itemContract[id]?.pocket==='items').flatMap(([id,n])=>s.party.map((mon,i)=>button(`${world.catalog.itemContract[id].name} ×${n} → ${i+1}`,`use:${id}:${mon.instanceId}`))).join('')}</details>`:'';
  root.innerHTML=`<h1>Canonical 20260927 · 내부 QA</h1><p>${esc(map.label)} · (${Math.floor(s.position.x/48)}, ${Math.floor(s.position.y/48)}) · ${esc(view.objective)}</p><p role="status">${esc(message)}</p><p data-feedback aria-hidden="true"></p>${battleMarkup||`${candidateViewport(world)}<div aria-label="이동">${['up','left','down','right'].map((dir,i)=>button(['↑','←','↓','→'][i],`move:${dir}`)).join('')}</div><details><summary>주변 조사 위치</summary>${near.filter(p=>p.kind!=='shop').map(p=>button(p.label,`point:${p.id}`)).join('')||'조사 위치가 없습니다.'}</details>${shopMarkup}${itemMarkup}`}${candidatePanel(view,prefs)}<footer><p>QA snapshot은 사용자 SAVE 1–3과 분리됩니다.</p>${button('QA snapshot 저장','save')}${button('새 QA 시작','reset')}</footer>`;
  clearInterval(feedbackTimer);if(message){const node=root.querySelector('[data-feedback]'),delay=prefs.reducedMotion||prefs.textSpeed==='instant'?0:prefs.textSpeed==='fast'?8:28;if(delay){let i=0;feedbackTimer=setInterval(()=>{node.textContent=message.slice(0,++i);if(i>=message.length)clearInterval(feedbackTimer)},delay)}else node.textContent=message}
  root.querySelectorAll('[data-action]').forEach(node=>node.onclick=async()=>{const action=node.dataset.action;
   if(action.startsWith('battle:')){try{const [,type,value,...rest]=action.split(':'),request=type==='move'?{type,moveId:value}:type==='switch'?{type,index:Number(value)}:type==='capture'?{type,ballId:value}:type==='item'?{type,itemId:value,instanceId:rest.join(':'),transactionId:`qa:${Date.now()}:${Math.random()}`}:{type};activeBattle=world.actBattle(request);render('전투 행동 적용')}catch(error){render(error.message)}return}
   if(busy)return;
   if(action.startsWith('tab:')){prefs.tab=action.slice(4);render();return}
   if(action==='save'){persist();render('QA snapshot 저장 완료');return}
   if(action==='reset'){storage.removeItem(CANDIDATE_QA_KEY);world.dispose();world=new CanonicalWorld({adapter,mode:'development',hooks});activeBattle=null;render('새 QA 세션');return}
   busy=true;try{let result;if(action.startsWith('move:')){result=await world.move(action.slice(5));activeBattle=null;persist();render(result.moved?'이동 완료':result.reason)}else if(action.startsWith('purchase:')){const match=/^purchase:(shop:[^:]+):([^:]+)$/.exec(action);if(!match)throw Error('잘못된 상점 항목');result=await world.interact(match[1],{itemId:match[2],quantity:1,transactionId:`qa:${Date.now()}:${Math.random()}`});persist();render(`${match[2]} 구매 완료`)}else if(action.startsWith('use:')){const match=/^use:([^:]+):(.+)$/.exec(action);if(!match)throw Error('잘못된 도구 선택');result=await world.useItem(match[1],match[2],`qa:${Date.now()}:${Math.random()}`);persist();render(`${match[1]} 사용 완료`)}else if(action.startsWith('point:')){const id=action.slice(6),p=world.definition.points[id];if(p.kind==='enhanced-league'||p.kind==='enhanced-league-info'){render('이 후보에는 해당 콘텐츠가 없습니다.');return}result=await world.interact(id,p.kind==='fishing'?{rod:p.rods?.[0],transactionId:`qa:${Date.now()}:${Math.random()}`}:{transactionId:`qa:${Date.now()}:${Math.random()}`});activeBattle=null;persist();render(result?.message??'조사 완료')}}catch(error){activeBattle=null;render(error.message)}finally{busy=false}
  });
  root.querySelector('[data-filter]')?.addEventListener('change',e=>{prefs.dexFilter=e.target.value;render()});root.querySelector('[data-area]')?.addEventListener('change',e=>{prefs.areaId=e.target.value;render()});
  root.querySelector('[data-motion]')?.addEventListener('change',e=>{prefs.reducedMotion=e.target.checked;render()});root.querySelector('[data-contrast]')?.addEventListener('change',e=>{prefs.highContrast=e.target.checked;render()});root.querySelector('[data-speed]')?.addEventListener('change',e=>{prefs.textSpeed=e.target.value;render()});root.querySelector('[data-type]')?.addEventListener('change',e=>{prefs.typeId=e.target.value;render()});
 };
 root.tabIndex=-1;root.addEventListener('keydown',event=>{const dir={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[event.key];if(dir&&event.target===root&&!activeBattle){event.preventDefault();event.stopPropagation();root.querySelector(`[data-action="move:${dir}"]`)?.click()}});
 render();return {adapter,world,getWorld:()=>world,root,dispose(){clearInterval(feedbackTimer);world.dispose();root.remove()}};
}
